import{_ as a,o as r,c as l,ag as e}from"./chunks/framework.DMXcdKmJ.js";const u=JSON.parse('{"title":"管理接入源与测试连接","description":"在工程数据中心创建和管理接入源，区分连接测试、工作台验证与运行态采集。","frontmatter":{"title":"管理接入源与测试连接","description":"在工程数据中心创建和管理接入源，区分连接测试、工作台验证与运行态采集。","kind":"how-to","status":"reviewed"},"headers":[],"relativePath":"zh/guide/access-sources.md","filePath":"zh/使用指南/管理接入源与测试连接.md"}'),i={name:"zh/guide/access-sources.md"};function o(s,t,d,n,h,c){return r(),l("div",null,[...t[0]||(t[0]=[e('<h1 id="管理接入源与测试连接" tabindex="-1">管理接入源与测试连接 <a class="header-anchor" href="#管理接入源与测试连接" aria-label="Permalink to &quot;管理接入源与测试连接&quot;">​</a></h1><p>本文帮助你保存一个接入源、确认它的连接参数，并找到下一步业务验证入口。测试连接成功不代表查询、订阅或持续采集已经可用。</p><h2 id="开始前" tabindex="-1">开始前 <a class="header-anchor" href="#开始前" aria-label="Permalink to &quot;开始前&quot;">​</a></h2><ul><li>已从平台公共入口登录，并有目标工程的数据中心访问与编辑权限。系统管理员、工程管理员和运维管理员仍受工程归属和可见范围约束。</li><li>工程当前允许开发，打开数据中心后没有占用、过期或权限错误。遇到这些提示，先恢复合法的工程访问，不要反复提交连接。</li><li>外部数据源已就绪，已取得它的地址、端口、数据库或服务名称以及所需凭据。测试时优先使用受控模拟器或测试数据库，不向真实设备试写。</li><li>需要 TLS 时，已确认服务端身份和可信 CA。若服务端要求客户端证书，还需要相互匹配的客户端证书与私钥。</li></ul><p>账号与入口有疑问时，先看<a href="/induframe-docs/zh/guide/login">登录与退出</a>和<a href="/induframe-docs/zh/concepts/access">入口与账号</a>。</p><h2 id="进入列表并找到连接" tabindex="-1">进入列表并找到连接 <a class="header-anchor" href="#进入列表并找到连接" aria-label="Permalink to &quot;进入列表并找到连接&quot;">​</a></h2><ol><li>在工程列表打开目标工程的<strong>数据中心</strong>，选择<strong>接入源</strong>。</li><li>输入连接名称搜索，或选择类型筛选：<strong>全部</strong>、<strong>内置运行库</strong>、<strong>数据库</strong>、<strong>消息/流</strong>。</li><li>根据需要切换卡片视图与列表视图。连接较多时，可选择分页容量或自动容量，再逐页查看。</li><li>从某个连接的<strong>工作台</strong>返回列表时，使用<strong>返回接入源</strong>。不要把整页浏览器刷新当作保留当前搜索条件的方法。</li></ol><p>确认当前工程和连接名称后再执行操作。另一个工程中的同名连接不是同一条记录。</p><h2 id="新建并测试外部连接" tabindex="-1">新建并测试外部连接 <a class="header-anchor" href="#新建并测试外部连接" aria-label="Permalink to &quot;新建并测试外部连接&quot;">​</a></h2><ol><li>点击<strong>新建连接</strong>，选择实际使用的数据源类型。</li><li>填写<strong>连接名称</strong>及该类型的连接参数。名称最多 100 个字符，同一工程内不能重名。</li><li>对支持连接测试的类型，点击<strong>测试连接</strong>，查看本次成功或失败提示。修改地址、认证、TLS 或拓扑后，应重新测试。</li><li>点击<strong>创建连接</strong>。弹窗关闭后，在列表中确认新连接存在；如已执行保存后的验证，再查看最新测试摘要。</li><li>用该连接的<strong>工作台</strong>进行一次实际业务验证，不要停在连接测试成功这一步。</li></ol><table tabindex="0"><thead><tr><th>类型</th><th>应核对的参数</th><th>连接测试之后</th></tr></thead><tbody><tr><td>MySQL、PostgreSQL、SQL Server</td><td>主机、端口、数据库、用户名、密码及当前类型可见的 TLS / 高级参数</td><td>在对应工作台验证实际查询与数据读取权限</td></tr><tr><td>Redis</td><td>单机 / 哨兵 / 集群、节点地址、数据库编号、认证；哨兵的主节点名称</td><td>在工作台查找并读取受控 Key；集群只使用数据库 0</td></tr><tr><td>MQTT</td><td>mqtt / mqtts / ws / wss、地址、独立端口、认证及客户端参数</td><td>在工作台验证所需的订阅或发布权限</td></tr><tr><td>Kafka</td><td>broker 地址、安全协议、SASL 机制与认证、TLS 材料</td><td>在工作台保存消费规则并拉取真实主题样本</td></tr><tr><td>TDengine</td><td>主机、端口、库名、认证、时区及 TLS 选择</td><td>在工作台验证实际查询</td></tr><tr><td>HTTP、WebSocket</td><td>连接名称等基础信息；具体请求或会话在工作台配置</td><td>没有通用<strong>测试连接</strong>按钮，分别验证实际请求或短时会话</td></tr></tbody></table><p>内置的<strong>关系库、时序库、实时库、消息中心</strong>不需要外部服务地址，也没有通用连接测试。请到对应工作台确认准备状态和所需业务操作；不要将打开入口等同于全部业务已经验收。</p><h3 id="mqtt-地址与-tls" tabindex="-1">MQTT 地址与 TLS <a class="header-anchor" href="#mqtt-地址与-tls" aria-label="Permalink to &quot;MQTT 地址与 TLS&quot;">​</a></h3><ul><li>UI 的传输选项是 mqtt、mqtts、ws、wss。WebSocket 路径属于地址路径，端口填写在独立端口字段，不追加到路径末尾。</li><li>切换协议会应用该协议的默认端口。使用自定义端口时，切换后重新核对地址、端口及路径，再测试。</li><li>加密不等于服务端身份验证。需要校验证书时，显式开启并核对服务端验证选项，提供可信 CA；不要通过关闭校验来掩盖错误 CA、主机名或过期证书。</li></ul><h2 id="编辑连接与保留凭据" tabindex="-1">编辑连接与保留凭据 <a class="header-anchor" href="#编辑连接与保留凭据" aria-label="Permalink to &quot;编辑连接与保留凭据&quot;">​</a></h2><ol><li>在目标连接上选择编辑，核对类型及原有公开参数。</li><li>已保存的密码和证书不会作为普通公开字段回填。留空表示保留原材料；输入新值后再清空，也不要当作已删除服务端秘密。</li><li>如需查看已保存密码，使用界面提供的查看入口。查看秘密与保存、测试连接不是同一种权限；被拒绝时不要从日志或共享文件取回秘密。</li><li>修改参数后重新测试，点击<strong>保存修改</strong>，再确认列表与已保存连接的验证结果。</li><li>如确实要清除秘密，只使用当前表单明确提供的清除操作；没有该操作时，不要猜测清空输入即可删除。</li></ol><p>草稿测试使用当前表单的参数，不会单独更新已保存连接的测试摘要。编辑时保留的密码可能需要额外查看权限；保留的私有 CA 或客户端材料也不应被假定会自动加入草稿测试。需要对照时，可在当前草稿显式重新提供已获授权的材料，再独立测试已保存连接。</p><p>关闭或重置表单会使原测试结果失效；如果修改了连接参数，旧成功结果不能授权新参数。不要把窗口关闭理解为远端网络操作已经全部结束。</p><h2 id="怎样理解状态和失败提示" tabindex="-1">怎样理解状态和失败提示 <a class="header-anchor" href="#怎样理解状态和失败提示" aria-label="Permalink to &quot;怎样理解状态和失败提示&quot;">​</a></h2><ul><li><strong>正常 / 异常 / 未测试</strong>需要结合最近已保存测试摘要理解。测试时间是一次验证记录，不是持续健康监控。</li><li><strong>已停用 / 配置不完整</strong>先检查启用状态或必填参数；没有通用测试能力的类型应到工作台确认。</li><li>草稿测试失败时，核对参数、认证、证书和目标可达性；不要将能建立 TCP 连接当作协议认证成功。</li><li>如果提示连接已保存但验证未通过，先确认记录仍在，再修正配置并重测；不要直接重复创建同名连接。</li><li>Redis 的 PING 成功不证明 SCAN、读取或写入权限。Kafka 的元数据握手不证明主题样本可读，MQTT 连接成功也不证明目标订阅或发布可用。</li></ul><h2 id="排序与删除" tabindex="-1">排序与删除 <a class="header-anchor" href="#排序与删除" aria-label="Permalink to &quot;排序与删除&quot;">​</a></h2><p>排序前清除搜索和类型筛选，并确保当前列表能完整展示全部连接。只有界面允许拖拽时才调整顺序，完成后刷新核对持久结果；筛选或分页状态下不要把当前局部顺序当作完整工程顺序。</p><p>删除只用于已经确认可丢弃的连接：</p><ol><li>点击目标连接的删除操作，先查看引用影响。</li><li>有阻断引用时，先处理引用，不要绕过提示。系统接入源不提供编辑、删除操作。</li><li>选择取消应保留记录；确认删除后，核对目标连接已从列表消失。</li></ol><p>删除连接不等于删除外部数据库或设备中的原始数据。界面提示保留并标记无效的数据点，也不等于全部关联配置自动迁移到了其他来源。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><p>数据库类连接可继续按<a href="/induframe-docs/zh/guide/sql-workbench">使用 SQL 工作台查询并生成数据点</a>核对查询、保存与真实 GET 的区别。</p><p>在所属工作台完成真实查询、Key 读取、请求或主题样本验证后，再检查生成的数据点及其开发态当前值。需要正式持续采集时，另行完成固定发布版本、部署、运行权限与断线恢复验证；不要把本页的连接测试结果作为运行态验收结论。</p>',28)])])}const p=a(i,[["render",o]]);export{u as __pageData,p as default};
